// attestation-roots.generated.ts — bundled offline snapshot of Google's
// Android Keystore hardware Key Attestation trust-anchor root certificates
// (D-04, RESEARCH.md Pattern 2).
//
// Fetched once from https://android.googleapis.com/attestation/root on
// 2026-07-22 (curl, no network fetch at verify-time — offline posture per
// D-04). The upstream endpoint returns a JSON array of PEM-encoded
// self-signed root certificates; both are bundled here as base64-encoded
// DER (the PEM body with header/footer/newlines stripped), decoded to
// `Uint8Array` at module load — never re-fetched.
//
// `verifyKeyAttestation` (verifiers/key-attestation.ts) walks a presented
// leaf-first chain via `X509ChainBuilder` using this pool as the ONLY
// trusted terminators — a chain that does not terminate at one of these
// exact root byte sequences is rejected (T-43-05).
//
// This snapshot must be refreshed out-of-band (re-run the fetch + this
// generation step, per SETUP.md's D-10 operational doc) — it is NOT
// auto-updated at runtime.
//
// Static import ONLY — dynamic require() breaks Metro (Phase 16-07 lesson),
// mirroring proof-flags.generated.ts's convention.

const PINNED_HARDWARE_ROOTS_DER_BASE64: string[] = [
  '',
  '',
]

/** Google's pinned Android hardware-attestation root certificate(s), DER-encoded. */
export const PINNED_HARDWARE_ROOTS_DER: Uint8Array[] = PINNED_HARDWARE_ROOTS_DER_BASE64.map(
  (b64) => new Uint8Array(Buffer.from(b64, 'base64'))
)
